// #799398 (7e5e16903a1b3d1d88799398) — отчёт кандидата в режиме поддержки Super Admin (?reason=support):
// AC1 колонка целиком в экране при скролле 0, AC2 колесо над транскриптом листает его до конца, потом страницу,
// AC5 минимум транскрипта = 160px (calc(8 * --line-height-cell), без нового токена; поведение не изменилось).
// Кейсы RPTASIDE-001, RPTASIDE-002. Только чтение — @prod-safe.
// Кандидат — QA-C2-2110-D2 (готовый отчёт с длинным транскриптом, постоянные тестовые данные QA).
import * as path from 'path';
import { test, expect, Page } from '@playwright/test';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const HASH = '#799398';
const REPORT = '/admin/support/candidates/71c9d469-5992-466f-a592-67e7a1c0f50e/report?reason=support';

async function openReport(page: Page) {
  await page.goto(REPORT);
  await expect(page.getByTestId('transcript')).toBeVisible({ timeout: 40_000 });
  await expect(page.locator('[data-testid=transcript] ol')).toBeVisible();
}

const state = (page: Page) =>
  page.evaluate(() => {
    const aside = document.querySelector('main aside') as HTMLElement;
    const ol = document.querySelector('[data-testid=transcript] ol') as HTMLElement;
    return {
      scrollY: Math.round(window.scrollY),
      innerHeight: window.innerHeight,
      asideBottom: Math.round(aside.getBoundingClientRect().bottom),
      minHeight: getComputedStyle(ol).minHeight,
      olTop: Math.round(ol.scrollTop),
      olMax: ol.scrollHeight - ol.clientHeight,
    };
  });

test.describe(`Отчёт в режиме поддержки Super Admin — боковая колонка и прокрутка (${HASH})`, () => {
  test(`минимум транскрипта 160px (1440×900, 1440×1024, 390), колонка целиком в экране при скролле 0 (1440) @desktop @prod-safe ${HASH}`, async ({ page }) => {
    for (const vp of [{ width: 1440, height: 900 }, { width: 1440, height: 1024 }, { width: 390, height: 844 }]) {
      await page.setViewportSize(vp);
      await openReport(page);
      const s = await state(page);
      // Источник: AC5 + вывод 17.11 — minHeight посчитан из calc(8 * --line-height-cell) = 160px.
      expect(s.minHeight, `min-height транскрипта @${vp.width}x${vp.height}`).toBe('160px');
      if (vp.width >= 1000) {
        // Источник: AC1 — колонка целиком в экране при скролле 0, с «סיבת הגישה» и крошками.
        expect(s.scrollY).toBe(0);
        expect(s.asideBottom, `низ колонки @${vp.width}x${vp.height}`).toBeLessThanOrEqual(s.innerHeight);
      }
    }
  });

  test(`колесо над транскриптом: сначала листает транскрипт до конца, затем страницу (1440×900) @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await openReport(page);
    const ol = page.locator('[data-testid=transcript] ol');
    const box = (await ol.boundingBox())!;
    await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
    const frame = () => page.evaluate(() => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))));
    const atEnd = async () => {
      const s = await state(page);
      return s.olTop >= s.olMax - 1;
    };

    // Источник: AC2 — пока транскрипт не дошёл до конца, страница стоит.
    await page.mouse.wheel(0, 300);
    await expect.poll(async () => (await state(page)).olTop, { message: 'транскрипт начал листаться' }).toBeGreaterThan(0);
    expect((await state(page)).scrollY, 'страница не должна ехать, пока транскрипт не дошёл до конца').toBe(0);

    // Докручиваем транскрипт до конца (список может догружаться — проверяем «дошёл» по факту).
    for (let i = 0; i < 40 && !(await atEnd()); i++) {
      await page.mouse.wheel(0, 300);
      await frame();
    }
    await expect.poll(atEnd, { message: 'транскрипт дошёл до конца' }).toBe(true);

    // Источник: AC2 — над колонкой, дошедшей до конца, колесо листает страницу.
    await expect
      .poll(async () => {
        await page.mouse.wheel(0, 300);
        return (await state(page)).scrollY;
      }, { message: 'страница пошла листаться после конца транскрипта', timeout: 15_000 })
      .toBeGreaterThan(0);
  });
});
